{
  "image_summary": "该图表展示了迪士尼流媒体业务从FY2022至FY2026（前9个月）的收入构成变化，重点反映了娱乐订阅费先升后降及体育业务相对稳定的趋势。",
  "chart_type": "多序列折线图",
  "title_text": "迪士尼流媒体业务收入构成",
  "footer_text": "数据来源：公司公告，迪士尼的财年为前一日历年10月开始",
  "axes": {
    "x_label": "财政年度 (Fiscal Year)",
    "y_label": "收入金额 (亿美元)",
    "x_categories": ["FY2022", "FY2023", "FY2024", "FY2025", "FY2026九个月"],
    "y_range_or_categories": ["0", "50", "100", "150", "200", "250", "300"]
  },
  "series": [
    {
      "name": "订阅费与转播费（娱乐）",
      "color": "#fc8166",
      "data_points": [["FY2022", 219], ["FY2023", 238], ["FY2024", 257], ["FY2025", 271], ["FY2026九个月", 226]],
      "meaning": "迪士尼娱乐板块的订阅及转播收入"
    },
    {
      "name": "订阅费与转播费（体育）",
      "color": "#7cc4f5",
      "data_points": [["FY2022", 119], ["FY2023", 121], ["FY2024", 121], ["FY2025", 119], ["FY2026九个月", 94]],
      "meaning": "ESPN等体育板块的订阅及转播收入"
    },
    {
      "name": "广告费（娱乐）",
      "color": "#a9c95e",
      "data_points": [["FY2022", 85], ["FY2023", 74], ["FY2024", 74], ["FY2025", 65], ["FY2026九个月", 51]],
      "meaning": "娱乐板块的广告业务收入"
    },
    {
      "name": "广告费（体育）",
      "color": "#b088d1",
      "data_points": [["FY2022", 44], ["FY2023", 39], ["FY2024", 44], ["FY2025", 44], ["FY2026九个月", 38]],
      "meaning": "体育板块的广告业务收入"
    }
  ],
  "table_data": {
    "headers": ["财政年度", "订阅费与转播费（娱乐）(亿)", "订阅费与转播费（体育）(亿)", "广告费（娱乐）(亿)", "广告费（体育）(亿)"],
    "rows": [
      ["FY2022", "219", "119", "85", "44"],
      ["FY2023", "238", "121", "74", "39"],
      ["FY2024", "257", "121", "74", "44"],
      ["FY2025", "271", "119", "65", "44"],
      ["FY2026九个月", "226", "94", "51", "38"]
    ]
  },
  "color_encoding": [
    {"color": "#fc8166", "meaning": "娱乐订阅/转播"},
    {"color": "#7cc4f5", "meaning": "体育订阅/转播"},
    {"color": "#a9c95e", "meaning": "娱乐广告"},
    {"color": "#b088d1", "meaning": "体育广告"}
  ],
  "visualization_spec": "该图采用横向布局的多序列折线图设计，画布比例约为16:9。背景为浅米色，中心隐约可见带有皇冠的卡通鱼形象水印。标题位于顶部左侧，“迪士尼”为白色粗体，“流媒体业务收入构成”为橙色（#fc8166）粗体。图表包含四条折线：橙色线代表娱乐订阅费，数值最高且波动最大；蓝色线代表体育订阅费，走势平稳；绿色线代表娱乐广告费，呈下降趋势；紫色线代表体育广告费，数值最低且平稳。Y轴刻度从0到300亿美元，间隔50；X轴为五个时间节点，其中最后一个标注为“九个月”。每个数据点均有清晰的黑色数值标签。底部有灰色底纹的数据来源说明文字以及“娱乐资本论”的品牌Logo。",
  "key_data_highlights": [
    "娱乐订阅费在FY2025达到峰值271亿美元后显著回落至226亿",
    "体育订阅费在FY2022-FY2025期间稳定在119-121亿区间",
    "娱乐广告费呈现持续下滑态势，从85亿降至51亿",
    "截至FY2026九月，总流媒体收入较峰值有明显收缩"
  ],
  "data_source_text": "公司公告，迪士尼的财年为前一日历年10月开始"
}
